static RasterImage AddTransparentColor(RasterImage inputImage) {    var outputImage = inputImage.Clone();    // find white and near-white pixels in the input image and create region from them    RasterColor colorLow = new RasterColor(245, 245, 245), colorHi = RasterColor.White;    outputImage.AddColorRgbRangeToRegion(colorLow, colorHi, RasterRegionCombineMode.Set);    // Fill the region with a single white color to enable setting it as a unique transparent color    FillCommand fill = new FillCommand(RasterColor.White);    fill.Run(outputImage);    outputImage.Transparent = true;    outputImage.TransparentColor = RasterColor.White;    outputImage.MakeRegionEmpty();    return outputImage; }static RasterImage AddAlphaTransparency(RasterImage inputImage) {    // createa an 8-bit image to use later as Alpha channel    RasterImage alpha = inputImage.CreateAlphaImage();    // Fill the alpha channel with white to cause all pixels to be opaque    FillCommand fill = new FillCommand(RasterColor.White);    fill.Run(alpha);    // find white and near-white pixels in the input image and create region from them    RasterColor colorLow = new RasterColor(245, 245, 245), colorHi = RasterColor.White;    inputImage.AddColorRgbRangeToRegion(colorLow, colorHi, RasterRegionCombineMode.Set);    // copy the region to the alpha image    alpha.SetRegion(null, inputImage.GetRegion(null), RasterRegionCombineMode.Set);    inputImage.MakeRegionEmpty();    // fill the region with black to represent transparent pixels.    fill.Color = RasterColor.Black;    fill.Run(alpha);    var outputImage = inputImage.Clone();    outputImage.SetAlphaImage(alpha);    return outputImage; } // Add code below to the Main() method after the call to SetLicense() using (RasterCodecs codecs = new RasterCodecs()) {    RasterImage image = codecs.Load(@"C:\LEADTOOLS22\Resources\Images\testframe1.jpg");           // Create a new image with trasparency alpha channel from near-white parts of the image    RasterImage imageWithAlpha = AddAlphaTransparency(image);    //save as 32-bit PNG to store alpha channel with image    codecs.Save(imageWithAlpha, @"imagePlusAlpha.png", RasterImageFormat.Png, 32);     // Create a new image with trasparency alpha channel from near-white parts of the image    RasterImage imageWithTransparentColor = AddTransparentColor(image);    //save as 8-bit GIF to store image with transparent color. Also the PNG format supports transparent color.    codecs.Save(imageWithTransparentColor, @"imageWithTranspColor.gif", RasterImageFormat.Gif, 8); } 